import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/commands.md","filePath":"modules/forge/commands.md","lastUpdated":0}`),a={name:`modules/forge/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiForge 的全部命令和权限节点, 以及每种场景先执行哪条命令</p><p>EmakiForge 的主命令是 <code>/emakiforge</code>, 别名 <code>/eforge</code>, <code>/ef</code>. 玩家用它打开锻造界面或配方书, 管理员用它重载配置, 列出配方和查看运行状态</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><p>主命令本身需要 <code>emakiforge.use</code> (默认 true). 子命令的额外权限如下表</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/ef help</code></td><td>显示这份帮助. 直接执行主命令不带参数时, 效果相同</td><td>仅需主命令权限</td></tr><tr><td><code>/ef forge</code></td><td>打开锻造界面. 只有玩家能执行, 在控制台执行会提示仅玩家可用</td><td>仅需主命令权限</td></tr><tr><td><code>/ef book</code></td><td>打开配方书. 只有玩家能执行, 在控制台执行会提示仅玩家可用</td><td><code>emakiforge.book</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef list &lt;type&gt;</code></td><td>列出已经加载的配置和它们的显示名. 目前只支持 <code>recipe</code> (写 <code>recipes</code> 也认), tab 补全只会提示 <code>recipe</code>; 填其他值会返回参数错误</td><td><code>emakiforge.admin</code></td></tr><tr><td><code>/ef reload</code></td><td>重新加载配置, 语言, GUI 模板和配方, 完成后回报重载了多少条配方, 多少个 GUI 模板, 以及花了多少时间</td><td><code>emakiforge.reload</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef convert-legacy [confirm]</code></td><td>把 <code>recipes/</code> 里 <code>materials[]</code>, <code>blueprint_requirements[]</code> 和 <code>result.*.outputs[]</code> 的旧 <code>item_sources</code> 写法迁移过来; 材料项按规格保留旧键. 不带参数只预演, 不写文件; 带 <code>confirm</code> (或 <code>--apply</code>) 才真正写文件, 并保留一份 <code>.bak</code> 备份</td><td><code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug stats</code></td><td>输出运行时的各项指标和配方加载报告 (写 <code>status</code> 效果一样)</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug on</code> / <code>off</code></td><td>总开关, 打开或关闭全部调试输出</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug player &lt;玩家&gt;</code></td><td>只跟踪某一个玩家的调试输出</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug module &lt;模块&gt;</code></td><td>打开某一个子模块的调试输出</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr></tbody></table><p>调试子模块可以填 <code>recipe</code>, <code>forge</code>, <code>gui</code>, <code>pdc</code>. <code>/ef debug</code> 下其余参数交给 CoreLib 的调试命令处理</p><p>别名 <code>eforge</code>, <code>ef</code> 与主命令的行为完全一致</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakiforge.use</code></td><td>true</td><td>使用主命令和锻造界面</td></tr><tr><td><code>emakiforge.book</code></td><td>true</td><td>打开配方书</td></tr><tr><td><code>emakiforge.reload</code></td><td>op</td><td>重载配置</td></tr><tr><td><code>emakiforge.debug</code></td><td>op</td><td>输出调试信息</td></tr><tr><td><code>emakiforge.admin</code></td><td>op</td><td>管理员权限</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要锻造装备</td><td><code>/ef forge</code></td><td>打开锻造界面</td></tr><tr><td>玩家找不到配方</td><td><code>/ef book</code></td><td>查看配方有没有加载</td></tr><tr><td>管理员改了配方或 GUI</td><td><code>/ef reload</code></td><td>重新加载 <code>recipes/</code>, <code>gui/</code>, 语言和运行时资源</td></tr><tr><td>不确定配方是否加载</td><td><code>/ef list recipe</code></td><td>查看当前加载了哪些配方</td></tr><tr><td>配方加载有告警或异常</td><td><code>/ef debug stats</code></td><td>查看运行时指标和配方加载报告</td></tr><tr><td>锻造结果异常</td><td><code>/ef debug module forge</code></td><td>打开 forge 子模块的调试输出</td></tr></tbody></table><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><h3 id="玩家打开锻造界面" tabindex="-1">玩家打开锻造界面 <a class="header-anchor" href="#玩家打开锻造界面" aria-label="Permalink to “玩家打开锻造界面”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef forge</span></span></code></pre></div><p>你把图纸放进图纸槽后, Forge 按图纸的物品来源匹配配方, 然后依次做条件检查, 容量检查, 材料检查, 品质计算和结果生成</p><h3 id="玩家查看配方书" tabindex="-1">玩家查看配方书 <a class="header-anchor" href="#玩家查看配方书" aria-label="Permalink to “玩家查看配方书”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef book</span></span></code></pre></div><p>配方书分页展示已经加载的配方. 你在配方书里看不到某个配方时, 先用 <code>/ef list recipe</code> 确认它有没有加载</p><h3 id="管理员重载" tabindex="-1">管理员重载 <a class="header-anchor" href="#管理员重载" aria-label="Permalink to “管理员重载”">​</a></h3><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef reload</span></span></code></pre></div><p>你改过 <code>recipes/</code>, <code>gui/</code> 或语言文件之后就用它. 重载成功会回报重载的配方数与 GUI 模板数. 调试配方时, 建议你重载前先备份正在改的那份配方文件</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};